// === Tab: mySketch.js ===
// Tree stem code forked form: https://openprocessing.org/sketch/2071621
// & credit to original designer of the tree: https://openprocessing.org/sketch/1991212
// Inspired by Alexis Middleton - https://persialou.com/diy-birch-tree-wall-art/

// ---------- SEED & VARIATIONS GLOBALES ----------

let mySeed;

let variations = {
  branchDensity: 1, // densité des branches
  wind: 0,          // orientation / vent
  squareLevel: 1    // quantité de carrés-feuilles
};

let PARTS = [];
let count = 2;
let counter = 0;
let palette = [];  // 3 couleurs aléatoires

// ---------- FONCTIONS UTILES ----------

function w(n) {
  if (n == null) return width;
  return width * n;
}

function h(n) {
  if (n == null) return height;
  return height * n;
}

function hsbShift(col, hShift, sShift, bShift) {
  return color(
    hue(col) + hShift,
    saturation(col) + sShift,
    brightness(col) + bShift
  );
}

function randNeg(n) {
  return (n == null)
    ? (random() < 0.5 ? 1 : -1)
    : (random() < 0.5 ? n : -n);
}

function ease(n) {
  return n ** 3;
}

// ---------- CLASSE PARTICLE (TRONC / BRANCHES / TWIGS) ----------

class particle {
  constructor(sx, sy, sc, ss, sd, sl, ls, tag, others) {
    this.tag = tag;
    this.pos = createVector(sx, sy);
    this.col = sc;
    this.siz = 1;
    this.asiz = ss;
    this.dir = sd;
    this.spd = (this.tag === "trunk") ? 2 : random(0.25, 2);
    this.life = sl;
    this.lifespan = ls;
    this.others = others;
    this.thshift = 0;
    this.tsshift = 0;
    this.tbshift = 0;
    this.rsiz = this.asiz * this.siz;
  }

  kill() {
    let index = this.others.indexOf(this);
    if (index > -1) {
      this.others.splice(index, 1);
    }
  }

  update() {
    this.rsiz = this.asiz * this.siz;

    // Déplacement + influence du vent
    let windFactor = (this.tag === "trunk") ? 0.2 : 1;
    this.pos.add(
      createVector(
        cos(radians(this.dir)) * this.spd,
        sin(radians(this.dir)) * this.spd
      )
    );

    this.dir +=
      random(-0.9, 1) *
      (this.tag === "trunk" && this.siz > 0.7
        ? 1
        : map(this.life, 0, this.lifespan, 1, 5)) +
      variations.wind * 0.001 * windFactor;

    if (random() < (this.tag === "branch" ? 0.003 : 0.005) && this.tag !== "trunk") {
      this.dir += randNeg(72) * 0;
    }

    this.siz = lerp(this.siz, 0, random(0.015));

    if (this.rsiz < 0.1 || this.spd > this.rsiz) {
      this.kill();
    }

    this.col = hsbShift(
      this.col,
      random(this.thshift),
      random(this.tsshift),
      random(this.tbshift)
    );

    // Création de nouvelles branches (densité influencée)
    if (random() < 0.03 * variations.branchDensity &&
        this.tag === "trunk" && this.siz < 0.55) {

      this.others.push(
        new particle(
          this.pos.x,
          this.pos.y,
          this.col,
          this.rsiz,
          this.dir + randNeg(random(15, 30)),
          this.life,
          this.lifespan,
          "branch",
          this.others
        )
      );
    }

    if (random() < 0.01 * variations.branchDensity && this.tag === "branch") {
      this.others.push(
        new particle(
          this.pos.x,
          this.pos.y,
          this.col,
          this.rsiz,
          this.dir,
          this.life,
          this.lifespan,
          "branch",
          this.others
        )
      );
    }

    if (random() < map(this.siz, 0, 0.25, 0.5, 0.3) * variations.branchDensity &&
        this.tag === "branch" && this.siz < 0.25) {

      this.others.push(
        new particle(
          this.pos.x,
          this.pos.y,
          this.col,
          (this.siz ** 0.5) * this.rsiz,
          this.dir + randNeg(random(5, 20)),
          0,
          random(this.lifespan * 0.05),
          "twig",
          this.others
        )
      );
    }

    // Dessin
    noStroke();
    fill(this.col);
    stroke(random(50));
    strokeWeight((this.siz * this.asiz) / 26);

    line(
      this.pos.x,
      this.pos.y,
      this.pos.x + random(this.siz * this.asiz) / 2,
      this.pos.y
    );

    if (round(random(1)) === 0) {
      circle(this.pos.x + (this.siz * this.asiz), this.pos.y, 1);
    }

    // Carrés-feuilles en fin de vie
    if (this.life > this.lifespan) {
      if (counter > 490 && random() < variations.squareLevel * 0.1) {
        let s = random(10, 25);
        rect(this.pos.x, this.pos.y, s, s);
      }
      this.kill();
    }

    this.life++;
  }
}

// ---------- SETUP & DRAW ----------

function setup() {
  createCanvas(1300, 900);

  // Seed aléatoire (pour info) + seed p5
  mySeed = floor(Math.random() * 999999);
  randomSeed(mySeed);
  noiseSeed(mySeed);

  // Variations aléatoires
  variations.branchDensity = random(0.5, 1.5);
  variations.wind = random(-25, 25);
  variations.squareLevel = floor(random(1, 6)); // 1 à 5

  // Affichage seed + variations
  createP("Seed : " + mySeed)
    .style("font-size:18px; font-weight:bold; margin:4px 0; color:black;");

  let densLabel =
    variations.branchDensity < 0.8 ? "faible" :
    variations.branchDensity > 1.2 ? "élevée" : "moyenne";

  let ventLabel =
    variations.wind < -5 ? "vers la gauche" :
    variations.wind > 5 ? "vers la droite" : "léger";

  createP(
    "Variations — densité des branches : " + densLabel +
    " | vent : " + ventLabel +
    " | carrés-feuilles (niveau) : " + variations.squareLevel
  )
    .style("font-size:14px; margin:0 0 10px 0; color:#444;");

  // Préparation du dessin
  colorMode(HSB, 360, 100, 100);
  background(0, 0, 100);

  // 3 couleurs aléatoires
  palette = [];
  for (let i = 0; i < 3; i++) {
    palette.push(
      color(
        random(360),
        random(40, 100),
        random(40, 100)
      )
    );
  }

  // Troncs initiaux
  PARTS = [];
  for (let i = 0; i < count; i++) {
    let c = random(palette);
    PARTS.push(
      new particle(
        w(0.5),
        h(0.95),
        c,
        100,
        270,
        0,
        500,
        "trunk",
        PARTS
      )
    );
  }

  // Sol
  fill(0);
  rect(0, height, width, -40);

  // Quelques carrés initiaux liés à squareLevel
  for (let i = 0; i < variations.squareLevel; i++) {
    var s = random(150, 250);
    rect(random(20, 100), random(20, 50), s, s);
  }
}

function draw() {
  counter++;
  push();
  translate(-50, 100);
  for (let p of PARTS) {
    p.update();
  }
  pop();
}

function smoothstep(start, end, amount) {
  amount = Math.max(0, Math.min(1, amount));
  return (amount * amount * (3 - 2 * amount)) * (end - start) + start;
}

